import pathlib

import jax
import jax.numpy as jnp
import numpy as np
import pytest
import torch

from openpi.models import rtc as _rtc

# Generated by `testdata/generate_rtc_lerobot_reference.py` from LeRobot's RTC implementation.
_REFERENCE_PATH = pathlib.Path(__file__).parent / "testdata" / "rtc_lerobot_reference.npz"

_SCHEDULES = {
    "ZEROS": _rtc.PrefixSchedule.ZEROS,
    "ONES": _rtc.PrefixSchedule.ONES,
    "LINEAR": _rtc.PrefixSchedule.LINEAR,
    "EXP": _rtc.PrefixSchedule.EXP,
}


@pytest.fixture(scope="module")
def reference() -> dict[str, np.ndarray]:
    with np.load(_REFERENCE_PATH) as data:
        return dict(data)


@pytest.mark.parametrize("schedule", list(_SCHEDULES))
def test_prefix_weights_match_lerobot(reference, schedule: str):
    for i, (delay, horizon, total) in enumerate(reference["weights/cases"]):
        weights = _rtc.get_prefix_weights(int(delay), int(horizon), int(total), _SCHEDULES[schedule])
        np.testing.assert_allclose(weights, reference[f"weights/{schedule}/{i}"], atol=1e-6, err_msg=f"case {i}")


def _guidance_inputs_for_case(reference, schedule: str, i: int):
    """Builds openpi guidance inputs that are equivalent to the LeRobot call of the given reference case."""
    _, horizon, dim, _, prefix_dim, delay, exec_horizon, time, max_weight = reference["denoise/cases"][i]
    key = f"denoise/{schedule}/{i}"
    config = _rtc.RTCConfig(
        execution_horizon=int(exec_horizon),
        max_guidance_weight=float(max_weight),
        prefix_schedule=_SCHEDULES[schedule],
    )
    prefixes, weights = [], []
    for prefix in reference[f"{key}/prefix"]:
        # LeRobot zero-pads the prefix to the model action dim and guides all dims.
        padded = np.zeros((len(prefix), int(dim)), dtype=np.float32)
        padded[:, : int(prefix_dim)] = prefix
        p, w = _rtc.make_guidance_inputs(
            padded, inference_delay=int(delay), action_horizon=int(horizon), action_dim=int(dim), config=config
        )
        prefixes.append(p)
        weights.append(w)
    return (
        reference[f"{key}/x_t"],
        reference[f"{key}/v_t"],
        np.float32(time),
        np.stack(prefixes),
        np.stack(weights),
        float(max_weight),
        reference[f"{key}/guided"],
    )


@pytest.mark.parametrize("schedule", list(_SCHEDULES))
def test_guided_velocity_jax_matches_lerobot(reference, schedule: str):
    guide = jax.jit(_rtc.guide_velocity_jax)
    for i in range(len(reference["denoise/cases"])):
        x_t, v_t, time, prefix, weights, max_weight, expected = _guidance_inputs_for_case(reference, schedule, i)
        guided = guide(x_t, v_t, jnp.float32(time), prefix, weights, max_weight)
        np.testing.assert_allclose(np.asarray(guided), expected, rtol=1e-5, atol=1e-5, err_msg=f"case {i}")


@pytest.mark.parametrize("schedule", list(_SCHEDULES))
def test_guided_velocity_torch_matches_lerobot(reference, schedule: str):
    for i in range(len(reference["denoise/cases"])):
        x_t, v_t, time, prefix, weights, max_weight, expected = _guidance_inputs_for_case(reference, schedule, i)
        guided = _rtc.guide_velocity_torch(
            torch.from_numpy(x_t),
            torch.from_numpy(v_t),
            torch.tensor(time),
            torch.from_numpy(prefix),
            torch.from_numpy(weights),
            max_weight,
        )
        np.testing.assert_allclose(guided.numpy(), expected, rtol=1e-5, atol=1e-5, err_msg=f"case {i}")


@pytest.mark.parametrize("time", [1.0, 0.9, 0.5, 0.1, 0.0])
def test_guidance_weight_is_finite_and_bounded(time: float):
    weight_jax = float(jax.jit(_rtc.guidance_weight_jax)(jnp.float32(time), 10.0))
    weight_torch = float(_rtc.guidance_weight_torch(torch.tensor(time), 10.0))
    assert 0.0 <= weight_jax <= 10.0
    assert weight_jax == pytest.approx(weight_torch, rel=1e-6)


def test_zero_weights_leave_velocity_unchanged():
    rng = np.random.default_rng(0)
    x_t, v_t, prefix = (rng.standard_normal((2, 10, 4)).astype(np.float32) for _ in range(3))
    weights = np.zeros_like(x_t)
    np.testing.assert_array_equal(np.asarray(_rtc.guide_velocity_jax(x_t, v_t, 1.0, prefix, weights, 10.0)), v_t)
    guided = _rtc.guide_velocity_torch(
        torch.from_numpy(x_t),
        torch.from_numpy(v_t),
        torch.tensor(1.0),
        torch.from_numpy(prefix),
        torch.zeros(2, 10, 4),
        10.0,
    )
    np.testing.assert_array_equal(guided.numpy(), v_t)


def test_make_guidance_inputs_without_prefix():
    config = _rtc.RTCConfig()
    for prefix in (None, np.zeros((0, 4))):
        p, w = _rtc.make_guidance_inputs(prefix, inference_delay=3, action_horizon=10, action_dim=4, config=config)
        assert p.shape == w.shape == (10, 4)
        assert not p.any()
        assert not w.any()


def test_make_guidance_inputs_truncates_and_masks():
    prefix = np.arange(15 * 4, dtype=np.float32).reshape(15, 4)
    p, w = _rtc.make_guidance_inputs(
        prefix,
        inference_delay=2,
        action_horizon=10,
        action_dim=4,
        config=_rtc.RTCConfig(prefix_schedule=_rtc.PrefixSchedule.ONES),
        num_guided_action_dims=3,
    )
    np.testing.assert_array_equal(p, prefix[:10])
    np.testing.assert_array_equal(w[:, :3], 1.0)
    np.testing.assert_array_equal(w[:, 3], 0.0)


def test_make_guidance_inputs_default_horizon_is_prefix_length():
    p, w = _rtc.make_guidance_inputs(
        np.ones((6, 2), dtype=np.float32),
        inference_delay=2,
        action_horizon=10,
        action_dim=2,
        config=_rtc.RTCConfig(),
    )
    np.testing.assert_array_equal(p[6:], 0.0)
    np.testing.assert_array_equal(w[:2], 1.0)
    assert np.all(np.diff(w[:, 0]) <= 0)
    np.testing.assert_array_equal(w[6:], 0.0)
    assert np.all(w[2:6] > 0)
